import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Header from '../components/Header';
import TitleFooter from '../components/TitleFooter';

import { useCoach } from '../contexts/Coach';
import './Title.css';

//TODO figure out storage for graphic
// import thmGraphic from '../assets/images/thm_graphic.png';
const thmGraphic = "data:image/png;base64,"

export default function Title() {
    const navigate = useNavigate();
    const { updateCoachProfile } = useCoach();

    const [coaches, setCoaches] = useState([]);
    const [selectedId, setSelectedId] = useState("");

    // Load coachesList from the global window object (if available)
    useEffect(() => {
        if (window.coachesList && Array.isArray(window.coachesList)) {
            setCoaches(window.coachesList);
        }
    }, []);

    const handleCoachChange = (event) => {
        const chosenId = event.target.value;
        setSelectedId(chosenId);

        // Find the matching coach
        const chosenCoach = coaches.find(
            (c) => c.record_id.toString() === chosenId
        );
        if (!chosenCoach) return;

        // Update context with Coach info
        updateCoachProfile({
            record_id: chosenCoach.record_id,
            name: `${chosenCoach.fname} ${chosenCoach.lname}`,
            // add any other fields you want to store in context
        });

        // Navigate right away
        navigate("/home");
    };

    return (
        <>
            <Header showBack={false} />
            <main id="title">
                <div className="content">
                    <img src={thmGraphic} alt="THM Graphic" className="graphic" />
                    <h1>Clinical Coach</h1>
                    <div className="dropdown-wrapper">
                        <select value={selectedId} onChange={handleCoachChange}>
                            <option value="">Select Coach to Begin</option>
                            {coaches.map((coach) => (
                                <option key={coach.record_id} value={coach.record_id}>
                                    {coach.fname} {coach.lname}
                                </option>
                            ))}
                        </select>
                    </div>
                </div>
            </main>
            <TitleFooter />
        </>
    );
}
